"""Synthetic sample datasets (generated by TorusPlot's own script; not real measurements).

The CSV files live in ``examples/`` at the repository root and are produced by
``examples/generate_examples.py`` from the functions below with fixed random seeds.
``load_sample(name)`` reads the CSV when present and otherwise regenerates the data.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd

from .parse import build_table
from .tables import DataTable

EXAMPLES_DIR = Path(__file__).resolve().parents[2] / "examples"

#: name -> file, table kind, title (also used as the default axis label), description, build options
SAMPLES: dict[str, dict] = {
    "nanoparticle_size": {
        "file": "nanoparticle_size.csv",
        "kind": "column",
        "title": "Nanoparticle diameter (nm)",
        "description": "SYNTHETIC. Hydrodynamic diameter (nm) of lipid nanoparticles made by four "
        "synthesis methods, 8 batches each. Try: one-way ANOVA + Tukey, bar + points.",
        "options": {},
    },
    "dose_response": {
        "file": "dose_response_cytotoxicity.csv",
        "kind": "xy",
        "title": "Viability (%)",
        "description": "SYNTHETIC. Cell viability (%) versus drug dose (uM) for a free drug and a "
        "nanoformulation, 3 replicates per dose. Try: nonlinear regression (4PL), dose-response curve.",
        "options": {"replicates": 3},
    },
    "cell_uptake": {
        "file": "cell_uptake_timecourse.csv",
        "kind": "grouped",
        "title": "Uptake (a.u.)",
        "description": "SYNTHETIC. Mean fluorescence (a.u.) at 1, 4 and 24 h for three formulations, "
        "4 biological replicates each. Try: two-way ANOVA + Tukey, grouped bars.",
        "options": {"replicates": 4, "row_label": "Time", "column_label": "Formulation"},
    },
    "cell_uptake_cells": {
        "file": "cell_uptake_superplot.csv",
        "kind": "multiple_variables",
        "title": "Per-cell uptake",
        "description": "SYNTHETIC. Per-cell uptake for two treatments; 20 cells in each of 3 independent "
        "experiments. Try: nested (replicate-aware) analysis, SuperPlot.",
        "options": {},
    },
    "survival": {
        "file": "survival.csv",
        "kind": "multiple_variables",
        "title": "Survival study",
        "description": "SYNTHETIC. Time to event (days) for three treatment groups of 12 animals; "
        "event = 1 (died) or 0 (censored). Try: Kaplan-Meier + log-rank, survival curve.",
        "options": {},
    },
    "paired": {
        "file": "paired_before_after.csv",
        "kind": "column",
        "title": "Tumour volume (mm3)",
        "description": "SYNTHETIC. Tumour volume (mm3) in 10 animals before and after treatment "
        "(each row is one animal). Try: paired t test, before-after plot.",
        "options": {},
    },
    "contingency": {
        "file": "contingency_response.csv",
        "kind": "contingency",
        "title": "Response by treatment",
        "description": "SYNTHETIC. Number of responders and non-responders for treated and control "
        "groups. Try: Fisher's exact test, odds ratio.",
        "options": {"column_label": "Outcome"},
    },
}


def _frame(name: str) -> pd.DataFrame:
    rng = np.random.default_rng({"nanoparticle_size": 11, "dose_response": 12, "cell_uptake": 13,
                                 "cell_uptake_cells": 14, "survival": 15, "paired": 16, "contingency": 17}[name])
    if name == "nanoparticle_size":
        spec = [("Bulk mixing", 142.0, 14.0), ("Sonication", 121.0, 11.0), ("Extrusion", 104.0, 7.0), ("Microfluidic", 86.0, 5.0)]
        return pd.DataFrame({g: np.round(rng.normal(m, s, 8), 1) for g, m, s in spec})
    if name == "dose_response":
        dose = np.array([0.01, 0.03, 0.1, 0.3, 1.0, 3.0, 10.0, 30.0, 100.0])

        def hill(ic50: float, slope: float) -> np.ndarray:
            return 4.0 + (98.0 - 4.0) / (1.0 + (dose / ic50) ** slope)

        data = {"Dose (uM)": dose}
        for label, ic50, slope in [("Free drug", 4.2, 1.1), ("Nanoformulation", 0.85, 1.3)]:
            for rep in range(3):
                data[f"{label}:{rep + 1}"] = np.round(hill(ic50, slope) + rng.normal(0, 3.2, dose.size), 1)
        return pd.DataFrame(data)
    if name == "cell_uptake":
        times = ["1 h", "4 h", "24 h"]
        forms = [("Free dye", [18.0, 26.0, 31.0]), ("Nanoparticle", [30.0, 58.0, 96.0]), ("Targeted NP", [41.0, 92.0, 171.0])]
        data: dict[str, list] = {"Time": times}
        for label, means in forms:
            for rep in range(4):
                data[f"{label}:{rep + 1}"] = [round(float(rng.normal(m, 0.09 * m + 2.0)), 1) for m in means]
        return pd.DataFrame(data)
    if name == "cell_uptake_cells":
        rows = []
        for treatment, base in [("Control", 100.0), ("Targeted NP", 138.0)]:
            for exp, shift in [("Exp 1", -14.0), ("Exp 2", 3.0), ("Exp 3", 16.0)]:
                for value in rng.normal(base + shift, 22.0, 20):
                    rows.append((treatment, exp, round(float(value), 1)))
        return pd.DataFrame(rows, columns=["Treatment", "Experiment", "Uptake"])
    if name == "survival":
        rows = []
        for group, scale in [("Vehicle", 21.0), ("Free drug", 33.0), ("Nano drug", 52.0)]:
            times = rng.weibull(2.2, 12) * scale
            for t in times:
                event = 1
                if t > 60.0:
                    t, event = 60.0, 0  # study ended on day 60
                elif rng.random() < 0.12:
                    t, event = t * rng.uniform(0.5, 0.95), 0  # lost to follow-up
                rows.append((round(float(t), 0) or 1.0, event, group))
        return pd.DataFrame(rows, columns=["Time (days)", "Event", "Group"])
    if name == "paired":
        before = rng.normal(412.0, 60.0, 10)
        after = before * rng.normal(0.78, 0.09, 10)
        return pd.DataFrame({"Before": np.round(before, 0), "After": np.round(after, 0)})
    if name == "contingency":
        return pd.DataFrame({"Group": ["Treated", "Control"], "Responder": [18, 7], "Non-responder": [6, 17]})
    raise KeyError(f"Unknown sample '{name}'. Available: {list(SAMPLES)}")


def sample_frame(name: str) -> pd.DataFrame:
    """The sample as a plain DataFrame (from the CSV in examples/ when available)."""
    if name not in SAMPLES:
        raise KeyError(f"Unknown sample '{name}'. Available: {list(SAMPLES)}")
    path = EXAMPLES_DIR / SAMPLES[name]["file"]
    if path.exists():
        return pd.read_csv(path, encoding="utf-8")
    return _frame(name)


def load_sample(name: str) -> DataTable:
    """Load a synthetic sample dataset as a ready-to-use table."""
    info = SAMPLES[name] if name in SAMPLES else None
    if info is None:
        raise KeyError(f"Unknown sample '{name}'. Available: {list(SAMPLES)}")
    table = build_table(info["kind"], sample_frame(name), info["title"], **info["options"])
    table.notes = info["description"]
    return table


def write_examples(directory: str | Path | None = None) -> list[Path]:
    """(Re)write every sample CSV; used by examples/generate_examples.py."""
    directory = Path(directory) if directory else EXAMPLES_DIR
    directory.mkdir(parents=True, exist_ok=True)
    paths = []
    for name, info in SAMPLES.items():
        path = directory / info["file"]
        _frame(name).to_csv(path, index=False, encoding="utf-8", lineterminator="\n")
        paths.append(path)
    return paths
